def note(name, ok, detail, category='user_flow'):
    row={'name':name,'passed':bool(ok),'category':category,'detail':detail}
    RESULTS.append(row)
    print(('PASS ' if ok else 'FAIL ')+name,flush=True)
    (ROOT/'diagnostics.json').write_text(json.dumps(RESULTS,ensure_ascii=False,indent=2),encoding='utf-8')
def run(name,fn,category='user_flow'):
    try:
        ok,detail=fn();note(name,ok,detail,category)
    except Exception as exc:
        note(name,False,{'unexpected_exception':repr(exc),'traceback':traceback.format_exc()},category)
def new(name,backend='json',sync='fsync',v2=False):
    d=ROOT/'probes'/name;d.mkdir(parents=True,exist_ok=True)
    cfg=SMEConfig();cfg.storage.path=str(d/('state.db' if backend=='sqlite' else 'state.json.gz'))
    cfg.storage.backend=backend;cfg.storage.autosave=True;cfg.storage.autosave_interval=1
    cfg.persistence.enabled=True;cfg.persistence.sync_mode=sync;cfg.persistence.checkpoint_every=100000
    cfg.policy.decay_enabled=False;cfg.region.auto_evolve=False
    if v2:
        cfg.extraction.enabled=True;cfg.extraction.mode='rules';cfg.factversion.enabled=True
    e=SpatialMemoryEngine(cfg);ENGINES.append(e);e.save();return e
def reload(e):
    e.wal.close();fresh=SpatialMemoryEngine(e.config);ENGINES.append(fresh)
    loaded=fresh.load();return fresh,loaded

for backend in ('json','sqlite'):
  for sync in ('fsync','grouped'):
