import pathlib,json,random,time,traceback
from concurrent.futures import ThreadPoolExecutor
from sme.config import SMEConfig
from sme.engine import SpatialMemoryEngine
ROOT=pathlib.Path(__file__).resolve().parent
out=[]
def make(name,backend='json',sync='fsync'):
    d=ROOT/'stress'/name;d.mkdir(parents=True,exist_ok=True)
    cfg=SMEConfig();cfg.storage.path=str(d/('state.db' if backend=='sqlite' else 'state.json.gz'));cfg.storage.backend=backend
    cfg.storage.autosave=True;cfg.persistence.enabled=True;cfg.persistence.sync_mode=sync;cfg.persistence.checkpoint_every=17
    cfg.policy.decay_enabled=False
    return SpatialMemoryEngine(cfg)
def restart(e):
    cfg=e.config;e.wal.close();r=SpatialMemoryEngine(cfg);r.load();return r
def simple(m):return {'text':m.text,'metadata':m.metadata,'tags':m.tags,'archived':m.archived}
for backend in ('json','sqlite'):
 for sync in ('fsync','grouped'):
  for seed in (71,83,97):
    name=f'random_{backend}_{sync}_{seed}';rng=random.Random(seed);e=make(name,backend,sync);e.save();expected={};actions={};errors=[];restarts=0
    start=time.perf_counter()
    for i in range(200):
      action=rng.choice(['add','add','update','delete','archive','restore','save']) if expected else 'add'
      actions[action]=actions.get(action,0)+1
      if action=='add':
        ns=rng.choice(['alice','bob','carol']);m=e.add(f'{ns}项目编号{seed}-{i}，记录第{i}次变更。',ns=ns,tags=[f'seed-{seed}']);expected[m.id]=simple(m)
      elif action=='update':
        mid=rng.choice(list(expected));e.update(mid,text=f'修订内容{seed}-{i}，保留命名空间。',metadata={'test_step':i});expected[mid]=simple(e.get(mid))
      elif action=='delete':
        mid=rng.choice(list(expected));e.delete(mid);expected.pop(mid)
      elif action=='archive':
        mid=rng.choice(list(expected));e.archive(mid);expected[mid]=simple(e.get(mid))
      elif action=='restore':
        mid=rng.choice(list(expected));e.restore(mid);expected[mid]=simple(e.get(mid))
      else:e.save()
      if i%41==40:
        e=restart(e);restarts+=1
        actual={mid:simple(m) for mid,m in e.memories.items()}
        if actual!=expected:errors.append({'step':i,'expected_count':len(expected),'actual_count':len(actual)})
      if i%31==0:
        for ns in ('alice','bob','carol'):
          hits=e.search('项目记录',ns=ns,top_k=7)
          if any(h.memory.metadata.get('ns')!=ns for h in hits):errors.append({'step':i,'namespace_leak':ns})
    e=restart(e);restarts+=1
    if {mid:simple(m) for mid,m in e.memories.items()}!=expected:errors.append({'final_state_mismatch':True})
    e.wal.close();row={'name':name,'passed':not errors,'seed':seed,'backend':backend,'sync':sync,'operations':200,'restarts':restarts,'actions':actions,'remaining':len(expected),'errors':errors,'seconds':time.perf_counter()-start};out.append(row)
    print(('PASS ' if row['passed'] else 'FAIL ')+name,flush=True)
    (ROOT/'stress.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
e=make('concurrent','json','grouped');e.save()
def writer(n):
    return [e.add(f'用户{n}项目并发记录{i}，编号 U{n}-{i}。',ns=f'user-{n}').id for i in range(80)]
def reader(n):
    for i in range(100):
        hits=e.search(f'用户{n}项目记录',ns=f'user-{n}',top_k=5)
        if any(h.memory.metadata.get('ns')!=f'user-{n}' for h in hits):raise AssertionError('Namespace leak')
    return True
def saver():
    for i in range(20):e.save()
    return True
start=time.perf_counter();errors=[];ids=[]
with ThreadPoolExecutor(max_workers=9) as pool:
    writes=[pool.submit(writer,n) for n in range(4)];reads=[pool.submit(reader,n) for n in range(4)];saving=pool.submit(saver)
    for f in writes:
        try:ids+=f.result()
        except Exception:errors.append(traceback.format_exc())
    for f in reads+[saving]:
        try:f.result()
        except Exception:errors.append(traceback.format_exc())
e=restart(e);missing=sorted(set(ids)-set(e.memories));e.wal.close()
out.append({'name':'mixed_concurrency','passed':not errors and not missing and len(ids)==320,'writers':4,'writes':320,'readers':4,'queries':400,'checkpoints':20,'recovered':len(e.memories),'missing_ids':missing,'errors':errors,'seconds':time.perf_counter()-start})
(ROOT/'stress.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(out[-1]),flush=True)

