cfg=SMEConfig();cfg.storage.path=str(work/'engine.json.gz');cfg.storage.autosave=True
cfg.persistence.enabled=True;cfg.persistence.sync_mode='fsync';cfg.persistence.checkpoint_every=10
cfg.policy.decay_enabled=False;cfg.maintenance.background=False;cfg.api.port=port
config=work/'config.json';config.write_text(json.dumps(cfg.to_dict()),encoding='utf-8')
env={**os.environ,'HF_HUB_OFFLINE':'1','TRANSFORMERS_OFFLINE':'1','PYTHONDONTWRITEBYTECODE':'1','NO_PROXY':'127.0.0.1,localhost'}
for key in list(env):
    if key.startswith('SME_'):env.pop(key)
with (work/'server.log').open('ab') as log:
    proc=subprocess.Popen([sys.executable,'-B','-m','sme.api','--config',str(config),'--host','127.0.0.1','--port',str(port)],cwd=str(work),env=env,stdout=log,stderr=subprocess.STDOUT,creationflags=subprocess.CREATE_NO_WINDOW if os.name=='nt' else 0)
info={'pid':proc.pid,'port':port,'url':f'http://127.0.0.1:{port}','config':str(config),'storage':cfg.storage.path}
(root/'service.json').write_text(json.dumps(info),encoding='utf-8')
with httpx.Client(trust_env=False,timeout=2) as c:
    for _ in range(30):
        if proc.poll() is not None:raise RuntimeError('Isolated server exited: '+(work/'server.log').read_text())
        try:
            r=c.get(info['url']+'/health')
            if r.status_code==200:break
        except httpx.HTTPError:pass
        time.sleep(.5)
    else:proc.terminate();raise RuntimeError('Isolated API failed to start')
print(json.dumps(info))
